import re, sys, os, json

def strip_comments(src):
    """Replace Lean comments with spaces (preserving newlines & offsets).
    Handles: -- line comments, /- ... -/ block comments (NESTED), /-- ... -/ docstrings,
    string literals "..." (with \\ escapes) and char literals so that '--' inside a
    string is not treated as a comment start."""
    out = list(src)
    i = 0
    n = len(src)
    depth = 0
    def blank(a, b):
        for k in range(a, b):
            if out[k] != '\n':
                out[k] = ' '
    while i < n:
        c = src[i]
        if depth > 0:
            if src.startswith('/-', i):
                depth += 1; blank(i, i+2); i += 2; continue
            if src.startswith('-/', i):
                depth -= 1; blank(i, i+2); i += 2; continue
            if out[i] != '\n': out[i] = ' '
            i += 1; continue
        # not in block comment
        if src.startswith('/-', i):
            depth = 1; blank(i, i+2); i += 2; continue
        if src.startswith('--', i):
            j = src.find('\n', i)
            if j == -1: j = n
            blank(i, j); i = j; continue
        if c == '"':
            j = i+1
            while j < n:
                if src[j] == '\\': j += 2; continue
                if src[j] == '"': j += 1; break
                j += 1
            i = j; continue
        if c == "'":
            # char literal like 'a' or '\n' ; but ' is also used in identifiers (foo')
            m = re.match(r"'(\\.|[^\\'])'", src[i:])
            if m and (i == 0 or not re.match(r"[A-Za-z0-9_₀-₉']", src[i-1])):
                i += m.end(); continue
            i += 1; continue
        i += 1
    return ''.join(out)

if __name__ == '__main__':
    mode = sys.argv[1]
    for path in sys.argv[2:]:
        src = open(path, encoding='utf-8').read()
        if mode == 'code':
            sys.stdout.write(strip_comments(src))
        elif mode == 'lines':
            code = strip_comments(src)
            for ln, line in enumerate(code.split('\n'), 1):
                print(f"{path}:{ln}:{line}")
